d^t\leftarrow -\sgn(d^T\nabla F(x^t))\frac{|d^T\nabla^2 F(x^t) d|}{\|d\|^3}d;
\end{equation}
\Else\ \{d$\_$type=SOL\}
%\State
\begin{equation}\label{dk-sol}
d^t\leftarrow d;
\end{equation}
\EndIf
\State Go to {\bf Line Search};
\Else
\State Call Algorithm~\ref{pro:meo} with $H=\nabla^2 F(x^t)$, $\varepsilon=\epsilon_H$, and probability parameter $\delta$;
\If{Algorithm~\ref{pro:meo} certifies that $\lambda_{\min}(\nabla^2 F(x^t))\ge-\epsilon_H$}
\State Output $x^t$ and terminate;
\Else\ \{Sufficiently negative curvature direction $v$ returned by Algorithm~\ref{pro:meo}\}
\State Set d$\_$type=NC and
\begin{equation}\label{dk-2nd-nc}
d^t\leftarrow -\sgn(v^T\nabla F(x^t))|v^T\nabla^2F(x^t)v|v;
\end{equation}
\State Go to {\bf Line Search};
\EndIf
\EndIf
\State{\bf Line Search:}
\If{d$\_$type=SOL}
\State Find $\alpha_t=\theta^{j_t}$, where $j_t$ is the smallest nonnegative integer $j$ such that
\begin{equation}\label{ls-sol}
F(x^t+\theta^jd^t)<F(x^t)-\eta\epsilon_H\theta^{2j}\|d^t\|^2;
\end{equation}
\Else\ \{d$\_$type=NC\}
\State Find $\alpha_t=\theta^{j_t}$, where $j_t$ is the smallest nonnegative integer $j$ such that
\begin{equation}\label{ls-nc}
F(x^t+\theta^jd^t)<F(x^t)-\eta\theta^{2j}\|d^t\|^3/2;
\end{equation}
\EndIf
\State $x^{t+1}=x^t+\alpha_td^t$;
\EndFor
\end{algorithmic}
}
\end{algorithm}

\begin{assumption}\label{asp:lowbd-knownfeas}		
\begin{enumerate}[{\rm (a)}]
\item An $\epsilon_1/2$-approximately feasible point $z_{\epsilon_1}$ of problem~\eqref{model:equa-cnstr}, namely satisfying $\|c(z_{\epsilon_1})\|\le\epsilon_1/2$, is known.	
\item There exist constants $\fh$, $\fl$ and $\gamma>0$, independent of $\epsilon_1$ and $\epsilon_2$,  such that
\begin{eqnarray}
&& f(z_{\epsilon_1})\le\fh, \label{hbd}\\
&& f(x)+\gamma\|c(x)\|^2/2\ge \fl,\quad \forall x\in\bR^n, \label{lbd}
\end{eqnarray}
 where $z_{\epsilon_1}$ is given in (a).
\item %{  For any $\epsilon \in (0,1)$ and the corresponding $z^0$ from (b),}
There exist some $\bdelta_f,\bdelta_c>0$ such that the set
\begin{equation}\label{nearly-feas-level-set}
\cS(\bdelta_f,\bdelta_c):=\{x:f(x)\le \fh+\bdelta_f,\ \|c(x)\|\le1+\bdelta_c\}
\end{equation}
%is compact, { with $\fh$ as in \eqref{hbd}}. 
is compact with $\fh$ given above. Also, $\nabla^2 f$ and $\nabla^2 c_i,\ i=1,2,\ldots,m$, are Lipschitz continuous in a convex open neighborhood, denoted by $\Omega(\bdelta_f,\bdelta_c)$, of $\cS(\bdelta_f,\bdelta_c)$.
\end{enumerate}
\end{assumption}

\begin{equation}\label{model:equa-cnstr-pert}
\min_{x\in \bR^n}\ f(x)\quad \st\ \tilde{c}(x):=c(x)-c(z_{\epsilon_1})=0,
\end{equation}

\begin{equation}\label{tL-tc}
\min_{x\in\bR^n} \big\{\widetilde{\cL}(x,\lambda^k,\rho_k):= f(x)+(\lambda^k)^T\tilde{c}(x)+\rho_k\|\tilde{c}(x)\|^2/2\big\}
\end{equation}

\begin{algorithm}[h]
\caption{A Newton-CG based AL method for problem
\eqref{model:equa-cnstr}}
\label{alg:2nd-order-AL-nonconvex}
{\small
Let $\gamma$ be given in Assumption \ref{asp:lowbd-knownfeas}.\\
\noindent\textbf{Input}: $\epsilon_1,\epsilon_2\in(0,1)$, $\Lambda>0$, $x^0\in\bR^n$, $\lambda^0 \in \mathcal{B}_{\Lambda}$, $\rho_0>2\gamma$, $\alpha\in(0,1)$, ${r}>1$, $\delta\in(0,1)$, and  $z_{\epsilon_1}$ given in Assumption~\ref{asp:lowbd-knownfeas}.
\begin{algorithmic}[1]
\State Set $k=0$.
\State Set $\tau_k^g=\max\{\epsilon_1, {r}^{k\log\epsilon_1/\log 2}\}$ and $\tau_k^H=\max\{\epsilon_2, {r}^{k\log\epsilon_2/\log 2}\}$.
\State  Call Algorithm \ref{alg:NCG} with $\epsilon_g=\tau_k^g$, $\epsilon_H=\tau_k^H$ and $u^0=x^{k}_{\init}$ to find an approximate solution $x^{k+1}$ to $\min_{x\in\bR^n}\widetilde{\cL}(x,\lambda^k;\rho_k)$ such that 
\begin{eqnarray}
&&\widetilde{\cL}(x^{k+1},\lambda^k;\rho_k)\le f(z_{\epsilon_1}),\ \|\nabla_x \widetilde{\cL}(x^{k+1},\lambda^k;\rho_k)\|\le\tau_k^g,\label{algstop:1st-order}\\
&&\lambda_{\min}(\nabla^2_{xx}\widetilde{\cL}(x^{k+1},\lambda^k;\rho_k))\ge-\tau_k^H\  \text{with probability at least } 1-\delta, \label{algstop:2nd-order}
\end{eqnarray}
where
\begin{equation}\label{def:initial-iterate-subprob}
x^k_{\init}=\left\{\begin{array}{ll}
z_{\epsilon_1}&\text{if }\ \widetilde{\cL}(x^k,\lambda^k;\rho_k)> f(z_{\epsilon_1}),\\
x^{k}&\text{otherwise},
\end{array}\right.\quad\text{for } k\ge 0.
\end{equation}\label{algstp:ALsubpb}
\State Set $\tilde{\lambda}^{k+1}=\lambda^k+\rho_k\tilde{c}(x^{k+1})$.
\State If $\tau_k^g\le\epsilon_1$, $\tau_k^H\le\epsilon_2$ and $\|c(x^{k+1})\|\le\epsilon_1$, then output $(x^{k+1},\tilde{\lambda}^{k+1})$ and terminate.\label{algstep:stop}
\State Set $\lambda^{k+1}=\Pi_{\mathcal{B}_\Lambda}(\tilde{\lambda}^{k+1})$.\label{algstep:proj-multiplier}
\State If $k=0$ or $\|\tilde{c}(x^{k+1})\|>\alpha\|\tilde{c}(x^k)\|$, set $\rho_{k+1}={r}\rho_k$. Otherwise, set $\rho_{k+1}=\rho_k$.\label{altstep:penalty}
\State Set $k\leftarrow k+1$, and go to step 2.
\end{algorithmic}
}
\end{algorithm}

In the rest of this section, we study the worst-case complexity of Algorithm \ref{alg:2nd-order-AL-nonconvex}. Since our method has two nested loops, particularly,  outer loops executed by the AL method and inner loops executed by the Newton-CG method for solving the AL subproblems, we consider the following measures of complexity for Algorithm \ref{alg:2nd-order-AL-nonconvex}.
\begin{itemize}
\item \emph{Outer iteration complexity}, which measures the number of outer iterations of Algorithm \ref{alg:2nd-order-AL-nonconvex};
\item  \emph{Total inner iteration complexity}, which measures the total number of iterations of the Newton-CG method that are performed in Algorithm \ref{alg:2nd-order-AL-nonconvex};
\item \emph{Operation complexity}, which measures the total number of matrix-vector products involving the Hessian of the augmented Lagrangian function that are evaluated in Algorithm \ref{alg:2nd-order-AL-nonconvex}.
\end{itemize}

For notational convenience, we rewrite $(\tau_k^g,\tau_k^H)$ arising in Algorithm \ref{alg:2nd-order-AL-nonconvex} as
\begin{equation}\label{omega-tolerance}
(\tau_k^g,\tau_k^H)=(\max\{\epsilon_1,\omega_1^k\},\max\{\epsilon_2,\omega_2^k\})\ \mbox{ with }\ (\omega_1,\omega_2):=({r}^{\log\epsilon_1/\log 2},{r}^{\log\epsilon_2/\log 2}),
\end{equation}
where $\epsilon_1$, $\epsilon_2$ and $r$ are the input parameters of Algorithm \ref{alg:2nd-order-AL-nonconvex}. Since $r>1$ and $\epsilon_1,\epsilon_2\in(0,1)$, it is not hard to verify that $\omega_1,\omega_2\in(0,1)$.
Also, we introduce the following quantity that will be used frequently later:
\begin{equation}
K_{\epsilon_1}:= \left\lceil \min\{k\ge 0:\omega_1^{k}\le\epsilon_1\} \right\rceil=\left\lceil\log\epsilon_1/\log\omega_1\right\rceil. \label{T-epsilon-g}
\end{equation}

\begin{remark}[{{\bf Upper bounds for $\overline{K}_{\epsilon_1}$ and $\{\rho_k\}$}}]\label{order-out-itera-penalty}
As observed from Theorem \ref{thm:out-itr-cmplxity-1}, the number of outer iterations of Algorithm \ref{alg:2nd-order-AL-nonconvex} for finding a stochastic  $(\epsilon_1,
\epsilon_2)$-SOSP of problem \eqref{model:equa-cnstr} is $\overline{K}_{\epsilon_1}+1$, which is at most of $\cO(|\log\epsilon_1|^2)$. In addition, the penalty parameters $\{\rho_k\}$ generated in this algorithm are at most of $\cO(\epsilon_1^{-2})$.
\end{remark}

One can observe from Assumption~\ref{asp:NCG-cmplxity}(b) that for all $x$ and $y\in \Omega$,
\begin{eqnarray}
&&\ \ \ \|\nabla F(y)-\nabla F(x)-\nabla^2 F(x)(y-x)\|\le L_H^F\|y-x\|^2/2, \label{apx-nxt-grad}\\
&&\ \ \ F(y)\le F(x) + \nabla F(x)^T(y-x) + (y-x)^T\nabla^2 F(x) (y-x)/2 +  L_H^F\|y-x\|^3/6. \label{desc-ineq}
\end{eqnarray}

\begin{algorithm}[h]
\caption{A capped conjugate gradient method}
\label{alg:capped-CG}
{\footnotesize
\begin{algorithmic}
\State \noindent\textit{Inputs}: symmetric matrix $H\in\bR^{n\times n}$, vector $g\neq0$, damping parameter $\varepsilon\in(0,1)$, desired relative accuracy $\zeta\in(0,1)$.
\State \textit{Optional input:} scalar $U\ge0$ (set to $0$ if not provided).
\State \textit{Outputs:} d$\_$type, $d$.
\State \textit{Secondary outputs:} final values of $U,\kappa,\widehat{\zeta},\tau,$ and $T$.
\State Set
\begin{equation*}
\textstyle
\bar{H}:=H+2\varepsilon I,\quad \kappa:=\frac{U+2\varepsilon}{\varepsilon},\quad\widehat{\zeta}:=\frac{\zeta}{3\kappa},\quad\tau:=\frac{\sqrt{\kappa}}{\sqrt{\kappa}+1},\quad T:=\frac{4\kappa^4}{(1-\sqrt{\tau})^2},
\end{equation*}
$y^0\leftarrow 0,r^0\leftarrow g,p^0\leftarrow -g, j\leftarrow 0$.
\If {$(p^0)^T \bar{H}p^0<\varepsilon\|p^0\|^2$}
\State Set $d\leftarrow p^0$ and terminate with d$\_$type = NC;
\ElsIf {\ $\|Hp^0\|>U\|p^0\|\ $}
\State Set $U\leftarrow\|Hp^0\|/\|p^0\|$ and update $\kappa,\widehat{\zeta},\tau, T$ accordingly;
\EndIf
\While{TRUE}
\State $\alpha_j\leftarrow (r^j)^T r^j/(p^j)^T\bar{H}p^j$; \{Begin Standard CG Operations\}
\State $y^{j+1}\leftarrow y^j+\alpha_jp^j$;
\State $r^{j+1}\leftarrow r^j+\alpha_j\bar{H}p^j$;
\State $\beta_{j+1}\leftarrow\|r^{j+1}\|^2/\|r^j\|^2$;
\State $p^{j+1}\leftarrow-r^{j+1}+\beta_{j+1}p^j$; \{End Standard CG Operations\}
\State $j\leftarrow j+1$;
\If {$\|Hp^j\|>U\|p^j\|$}
\State Set $U\leftarrow\|Hp^j\|/\|p^j\|$ and update $\kappa,\widehat{\zeta},\tau,T$ accordingly;
\EndIf
\If {\ $\|Hy^j\|>U\|y^j\|\ $}
\State Set $U\leftarrow\|Hy^j\|/\|y^j\|$ and update $\kappa,\widehat{\zeta},\tau,T$ accordingly;
\EndIf
\If {\ $\|Hr^j\|>U\|r^j\|\ $}
\State Set $U\leftarrow\|Hr^j\|/\|r^j\|$ and update $\kappa,\widehat{\zeta},\tau,T$ accordingly;
\EndIf
\If {$(y^j)^T\bar{H}y^j<\varepsilon\|y^j\|^2$}
\State Set $d\leftarrow y^j$ and terminate with d$\_$type = NC;
\ElsIf {\ $\|r^j\|\le\widehat{\zeta}\|r^0\|$}
\State Set $d\leftarrow y^j$ and terminate with d$\_$type = SOL;
\ElsIf{\ $(p^j)^T\bar{H}p^j<\varepsilon\|p^j\|^2$}
\State Set $d\leftarrow p^j$ and terminate with d$\_$type = NC;
\ElsIf {\ $\|r^j\|>\sqrt{T}\tau^{j/2}\|r^0\| $}
\State Compute $\alpha_j, y^{j+1}$ as in the main loop above;
\State Find $i\in\{0,\ldots,j-1\}$ such that
\[
(y^{j+1}-y^i)^T\bar{H}(y^{j+1}-y^i)<\varepsilon\|y^{j+1}-y^i\|^2;
\]
\State Set $d\leftarrow y^{j+1}-y^i$ and terminate with d$\_$type = NC;
\EndIf
\EndWhile
\end{algorithmic}
}
\end{algorithm}

\begin{algorithm}[h]
\caption{A randomized Lanczos based minimum eigenvalue oracle}
\label{pro:meo}
\noindent\textit{Input}: symmetric matrix $H\in\bR^{n\times n}$, tolerance $\varepsilon>0$, and probability parameter $\delta\in(0,1)$.\\
\noindent\textit{Output}: a sufficiently negative curvature direction $v$ satisfying $v^THv\le-\varepsilon/2$ and $\|v\|=1$; or a certificate that $\lambda_{\min}(H)\ge-\varepsilon$ with probability at least  $1-\delta$.\\
Apply the Lanczos method \cite{KW92LR} to estimate $\lambda_{\min}(H)$ starting with a random vector uniformly generated on the unit sphere, and run it for at most 
\begin{equation}\label{N-iter} 
N(\varepsilon,\delta):=\min\left\{n,1+\left\lceil\frac{\ln(2.75n/\delta^2)}{2}\sqrt{\frac{\|H\|}{\varepsilon}}\right\rceil\right\}
\end{equation}
iterations. If a unit vector $v$ with $v^THv \le -\varepsilon/2$ is found at some iteration, terminate immediately and return $v$.
\end{algorithm}

