\begin{theorem}%[{{\bf Complexity of Algorithm~\ref{alg:NCG}}}]
\label{thm:NCG-iter-oper-cmplxity}
Suppose that Assumption~\ref{asp:NCG-cmplxity} holds. Let 
\begin{equation}
T_1:=\left\lceil\frac{\Fh-\Fl}{\min\{c_{\rm sol},c_{\rm nc}\}}\max\{\epsilon_g^{-2}\epsilon_H,\epsilon_H^{-3}\}\right\rceil+\left\lceil\frac{\Fh-\Fl}{c_{\rm nc}}\epsilon_H^{-3}\right\rceil+1, \
T_2:=\left\lceil\frac{\Fh-\Fl}{c_{\rm nc}}\epsilon_H^{-3}\right\rceil+1,\label{T1}
\end{equation}
%where $\Fh=F(u^0)$, $\Fl$ is given in \eqref{lwbd-Hgupbd}, and $c_{\rm sol}$ and $c_{\rm nc}$ are defined in \eqref{csol} and \eqref{cnc}, respectively.
where $\Fh=F(u^0)$, $\Fl$ is given in \eqref{lwbd-Hgupbd}, and 
\beqa
&&c_{\rm sol} :=\eta\min\left\{\left[\frac{4}{4+\zeta+\sqrt{(4+\zeta)^2+8L^F_H}}\right]^2,\left[\frac{\min\{6(1-\eta),2\}\theta}{L^F_H}\right]^2\right\}, \label{csol} \\
&& c_{\rm nc} := \frac{\eta}{16} \min\left\{1,\left[\frac{\min\{3(1-\eta),1\}\theta}{L_H^F}\right]^2\right\}.   \label{cnc}
\eeqa
 Then the following statements hold.
\begin{enumerate}[{\rm (i)}]
\item The total number of calls of Algorithm~\ref{pro:meo} in Algorithm~\ref{alg:NCG} is at most $T_2$.	
\item The total number of calls of Algorithm~\ref{alg:capped-CG} in Algorithm~\ref{alg:NCG} is at most $T_1$.
\item {\rm ({\bf iteration complexity})} Algorithm~\ref{alg:NCG} terminates in at most $T_1+T_2$ iterations with 
\begin{equation}\label{NCG-iter} 
T_1+T_2=\cO((\Fh-\Fl)(L_H^F)^2\max\{\epsilon_g^{-2}\epsilon_H,\epsilon_H^{-3}\}).
\end{equation}
Also, its output $x^t$ satisfies $\|\nabla F(x^t)\|\le \epsilon_g$ deterministically and
$\lambda_{\min}(\nabla^2F(x^t))$ $\ge-\epsilon_H$ with probability at least $1-\delta$ for
some $0 \le t \le T_1+T_2$.
\item {\rm ({\bf operation complexity})} Algorithm~\ref{alg:NCG} requires at most 
\[
\widetilde{\cO}((\Fh-\Fl)(L_H^F)^2\max\{\epsilon_g^{-2}\epsilon_H,\epsilon_H^{-3}\}\min\{n,(U_H^F/\epsilon_H)^{1/2}\})
\]
matrix-vector products, where $U_H^F$ is given in \eqref{lwbd-Hgupbd}.
\end{enumerate}
\end{theorem}

To this end, we start by noting from \eqref{hbd}, \eqref{model:equa-cnstr-pert}, \eqref{tL-tc} and \eqref{def:initial-iterate-subprob} that
\beq \label{L-xinit}
\widetilde{\cL}(x^{k}_{\init},\lambda^k;\rho_k) \le \max\{\widetilde{\cL}(z_{\epsilon_1},\lambda^k;\rho_k),f(z_{\epsilon_1})\}=f(z_{\epsilon_1})\le \fh.
\eeq


\begin{lemma}%[{{\bf level- and lower-boundedness of $\widetilde{\cL}(\cdot,\lambda^k;\rho_k)$}}]
\label{lem:level-set-augmented-lagrangian-func}
Suppose that Assumption~\ref{asp:lowbd-knownfeas} holds. Let $(\lambda^k, \rho_k)$ be generated at the $k$th iteration of Algorithm~\ref{alg:2nd-order-AL-nonconvex} for some $k \ge 0$, and $\cS(\bdelta_f,\bdelta_c)$ and $x_{\init}^k$ be defined in \eqref{nearly-feas-level-set} and \eqref{def:initial-iterate-subprob}, respectively, and let $\fh$, $\fl$, $\bdelta_f$ and $\bdelta_c$ be given in Assumption~\ref{asp:lowbd-knownfeas}. Suppose that $\rho_0$ is sufficiently large such that $\delta_{f,1} \le \bdelta_f$ and  $\delta_{c,1} \le \bdelta_c$, where 
\begin{equation} 
\delta_{f,1}:=\Lambda^2/(2\rho_0)\quad and\quad \delta_{c,1}:=\sqrt{\frac{2(\fh-\fl+\gamma)}{\rho_0-2\gamma}+\frac{\Lambda^2}{(\rho_0-2\gamma)^2}}+\frac{\Lambda}{\rho_0-2\gamma}\label{def:delta0c-rhobar1xxx}.
\end{equation}
Then the following statements hold.
\begin{enumerate}[{\rm (i)}]
\item $\{x:\widetilde{\cL}(x,\lambda^k;\rho_k)\le \widetilde{\cL}(x^{k}_{\init},\lambda^k;\rho_k)\}\subseteq \cS(\bdelta_f,\bdelta_c)$.
\item $\inf_{x\in\bR^n} \widetilde{\cL}(x,\lambda^k;\rho_k) \ge\fl - \gamma-\Lambda\bdelta_c$.
\end{enumerate}
\end{lemma}

Using Lemma \ref{lem:level-set-augmented-lagrangian-func}, we can verify that the Newton-CG method (Algorithm \ref{alg:NCG}), starting with $u^0=x^{k}_{\init}$, is capable of finding an approximate solution $x^{k+1}$ of the AL subproblem $\min_{x\in\bR^n} \widetilde{\cL}(x,\lambda^k;\rho_k)$ satisfying \eqref{algstop:1st-order} and \eqref{algstop:2nd-order}. Indeed,
let $F(\cdot)=\widetilde{\cL}(\cdot,\lambda^k;\rho_k)$ and $u^0=x^{k}_{\init}$. By these and Lemma \ref{lem:level-set-augmented-lagrangian-func}, one can see that $\{x:F(x) \le F(u^0)\} \subseteq \cS(\bdelta_f,\bdelta_c)$. It then follows from this and Assumption \ref{asp:lowbd-knownfeas}(c) that the level set $\{x : F(x) \le F(u^0)\}$ is compact  and $\nabla^2 F$ is Lipschitz continuous on a convex open neighborhood of $\{x:F(x) \le F(u^0)\}$. Thus, such $F$ and $u^0$ satisfy Assumption \ref{asp:NCG-cmplxity}. Based on this and the discussion in Section \ref{sec:sbpb-solver}, one can conclude that Algorithm~\ref{alg:NCG}, starting with $u^0=x^{k}_{\init}$, is applicable to the AL subproblem $\min_{x\in\bR^n} \widetilde{\cL}(x,\lambda^k;\rho_k)$. Moreover, it follows from Theorem \ref{thm:NCG-iter-oper-cmplxity} that this algorithm with $(\epsilon_g,\epsilon_H)=(\tau_k^g,\tau_k^H)$ can produce a point $x^{k+1}$ satisfying \eqref{algstop:2nd-order} and also the second relation in \eqref{algstop:1st-order}. In addition, since this algorithm
is descent and its starting point is $x^{k}_{\init}$, its output $x^{k+1}$ must satisfy $\widetilde{\cL}(x^{k+1},\lambda^k;\rho_k) \le \widetilde{\cL}(x^{k}_{\init},\lambda^k;\rho_k)$, which along with \eqref{L-xinit} implies that $\widetilde{\cL}(x^{k+1},\lambda^k;\rho_k) \le f(z_{\epsilon_1})$ and thus $x^{k+1}$ also satisfies the first relation in \eqref{algstop:1st-order}.


\begin{theorem}%[{{\bf Well-definedness of Algorithm \ref{alg:2nd-order-AL-nonconvex}}}]
\label{subprob-solver}
Under the same settings as in Lemma \ref{lem:level-set-augmented-lagrangian-func}, the Newton-CG method (Algorithm \ref{alg:NCG}) applied to the AL subproblem $\min_{x\in\bR^n} \widetilde{\cL}(x,\lambda^k;\rho_k)$ with $u^0=x^{k}_{\init}$ finds a point $x^{k+1}$ satisfying \eqref{algstop:1st-order} and \eqref{algstop:2nd-order}.
\end{theorem}

\begin{theorem}%[{{\bf Output of Algorithm \ref{alg:2nd-order-AL-nonconvex}}}]
\label{thm:output-alg1}
Suppose that Assumption~\ref{asp:lowbd-knownfeas} holds and that $\rho_0$ is sufficiently large such that $\delta_{f,1} \le \bdelta_f$ and  $\delta_{c,1} \le \bdelta_c$, where
$\delta_{f,1}$ and $\delta_{c,1}$ are defined in \eqref{def:delta0c-rhobar1xxx}.
If Algorithm \ref{alg:2nd-order-AL-nonconvex} terminates at some iteration $k$, then $x^{k+1}$ is a deterministic $\epsilon_1$-FOSP of problem \eqref{model:equa-cnstr}, and moreover, it is an $(\epsilon_1,\epsilon_2)$-SOSP of \eqref{model:equa-cnstr} with probability at least $1-\delta$.
\end{theorem}

In view of \eqref{omega-tolerance}, \eqref{T-epsilon-g} and the fact that
\begin{equation}\label{epsw1-epsw2}
%\log\epsilon_1/\log\omega_1=\log2/\log r=\log\epsilon_2/\log\omega_2,
\log\epsilon_1/\log\omega_1=\log\epsilon_2/\log\omega_2=\log2/\log r,
\end{equation}
we see that $(\tau_k^g,\tau_k^H)=(\epsilon_1,\epsilon_2)$ for all $k\ge K_{\epsilon_1}$. This along with the termination criterion of Algorithm \ref{alg:2nd-order-AL-nonconvex} implies that it runs for at least $K_{\epsilon_1}$ iterations and  terminates once $\|c(x^{k+1})\|\le\epsilon_1$ for some $k\ge K_{\epsilon_1}$. As a result, to establish outer iteration complexity of Algorithm \ref{alg:2nd-order-AL-nonconvex}, it suffices to bound such  $k$. The resulting outer iteration complexity of Algorithm \ref{alg:2nd-order-AL-nonconvex} is presented below, whose proof is deferred to Section \ref{sec:pf-AL}.


\begin{theorem}%[{{\bf Outer iteration complexity of Algorithm \ref{alg:2nd-order-AL-nonconvex}}}]
\label{thm:out-itr-cmplxity-1}
Suppose that Assumption~\ref{asp:lowbd-knownfeas} holds and that $\rho_0$ is sufficiently large such that $\delta_{f,1} \le \bdelta_f$ and  $\delta_{c,1} \le \bdelta_c$, where
$\delta_{f,1}$ and $\delta_{c,1}$ are defined in \eqref{def:delta0c-rhobar1xxx}. Let
\begin{eqnarray}
&&{\rho}_{\epsilon_1}:=\max\left\{8(\fh-\fl+\gamma)\epsilon_1^{-2}+4\Lambda\epsilon_1^{-1}+2\gamma,2\rho_0\right\},\label{def:delta0c-rhobar1}\\
&&\overline{K}_{\epsilon_1}:=\inf\{k\ge K_{\epsilon_1}: \|c(x^{k+1})\|\le\epsilon_1\},\label{number-outer-iteration}
\end{eqnarray}
where $K_{\epsilon_1}$ is defined in \eqref{T-epsilon-g},  and $\gamma$, $\fh$ and $\fl$ are given in Assumption \ref{asp:lowbd-knownfeas}. Then $\overline{K}_{\epsilon_1}$ is finite, and Algorithm \ref{alg:2nd-order-AL-nonconvex} terminates at iteration $\overline{K}_{\epsilon_1}$ with
\begin{equation}\label{outer-iteration-cmplxty}
\overline{K}_{\epsilon_1}\le\left(\frac{\log({\rho}_{\epsilon_1}\rho_0^{-1})}{\log{r}}+1\right)\left(\left|\frac{\log(\epsilon_1(2\delta_{c,1})^{-1})}{\log \alpha}\right|+2\right)+1.
\end{equation}
Moreover, $\rho_k\le{r}{\rho}_{\epsilon_1}$ holds for $0 \le k \le \overline{K}_{\epsilon_1}$
\end{theorem}

\begin{lemma}\label{lem:SOL-NC-ppty}
Suppose that Assumption~\ref{asp:NCG-cmplxity} holds and the direction $d^t$ results from  the output $d$ of Algorithm \ref{alg:capped-CG} with a type specified in d$\_$type  at some iteration $t$ of Algorithm \ref{alg:NCG}. Then the following statements hold.
\begin{enumerate}[{\rm (i)}]
\item If d$\_$type=SOL, then  $d^t$ satisfies
\beqa
&\epsilon_H\|d^t\|^2\le (d^t)^T\left(\nabla^2 F(x^t)+2\epsilon_H I\right)d^t,\label{SOL-ppty-1}\\
&\|d^t\|\le1.1 \epsilon_H^{-1}\|\nabla F(x^t)\|,\label{SOL-ppty-2}\\
&(d^t)^T\nabla F(x^t)=-(d^t)^T\left(\nabla^2F(x^t)+2\epsilon_HI\right)d^t,\label{SOL-ppty-3}\\
&\|(\nabla^2F(x^t)+2\epsilon_HI)d^t+\nabla F(x^t)\|\le\epsilon_H\zeta\|d^t\|/2.\label{SOL-ppty-4}
\eeqa
\item If d$\_$type=NC, then  $d^t$ satisfies $(d^t)^T\nabla F(x^t)\le0$ and
\begin{equation}\label{NC-ppty}
(d^t)^T\nabla^2F(x^t)d^t/\|d^t\|^2=-\|d^t\|\le-\epsilon_H.
\end{equation}
\end{enumerate}
\end{lemma}

\begin{lemma}\label{lem:sol}
Suppose that Assumption~\ref{asp:NCG-cmplxity} holds and the direction $d^t$ results from  the output $d$ of Algorithm~\ref{alg:capped-CG} with d$\_$type=SOL at some iteration $t$ of Algorithm~\ref{alg:NCG}. Let $U_g^F$ and $c_{\rm sol}$ be given in \eqref{lwbd-Hgupbd} and \eqref{csol}, respectively.  Then the following statements hold.
\begin{enumerate}[{\rm (i)}]
\item The step length $\alpha_t$ is well-defined, and moreover,
\begin{equation}\label{lwbd-ak-sol}
\alpha_t\ge\min\left\{1,\sqrt{\frac{\min\{6(1-\eta),2\}}{1.1 L_H^F U_g^F}}\theta\epsilon_H\right\}.
\end{equation}
\item The next iterate $x^{t+1}=x^t+\alpha_td^t$ satisfies %$F(x^t)-F(x^{t+1})\ge c_{\rm sol}\min\{\|\nabla F(x^{t+1})\|^2\epsilon_H^{-1},\epsilon_H^3\}$.
\begin{equation}\label{suff-desc-sol}
F(x^t)-F(x^{t+1})\ge c_{\rm sol}\min\{\|\nabla F(x^{t+1})\|^2\epsilon_H^{-1},\epsilon_H^3\}.
\end{equation}
\end{enumerate}
\end{lemma}

\begin{proof}
One can observe that $F$ is descent along the iterates (whenever well-defined) generated by Algorithm~\ref{alg:NCG}, which together with $x^0=u^0$ implies that $F(x^t)\le F(u^0)$ and hence
$\|\nabla F(x^t)\|\le U^F_g$ due to \eqref{lwbd-Hgupbd}.
%Since $d^t$ { results from} the output $d$ of Algorithm~\ref{alg:capped-CG} with d$\_$type=SOL, it follows from Lemma~\ref{lem:SOL-NC-ppty}(i) that \eqref{SOL-ppty-1}-\eqref{SOL-ppty-4} hold for $d^t$.
%In particular, we see from \eqref{SOL-ppty-2} and \eqref{SOL-ppty-4} that $\|(\nabla^2F(x^t)+2\epsilon_HI)d^t+\nabla F(x^t)\|\le0.55\zeta\|\nabla F(x^t)\|$. Since we also have $\|\nabla F(x^t)\| > \epsilon_g$ in this case and recall that $ \zeta \in (0,1)$, we conclude that $d^t\neq 0$.
In addition, since $d^t$ results from the output $d$ of Algorithm~\ref{alg:capped-CG} with d$\_$type=SOL, one can see that $\|\nabla F(x^t)\| > \epsilon_g$ and \eqref{SOL-ppty-1}-\eqref{SOL-ppty-4} hold for $d^t$. Moreover, by $\|\nabla F(x^t)\| > \epsilon_g$ and \eqref{SOL-ppty-4}, one can conclude that $d^t\neq 0$.

We first prove statement (i). If \eqref{ls-sol} holds for $j=0$, then $\alpha_t=1$, which clearly implies that \eqref{lwbd-ak-sol} holds. We now suppose that \eqref{ls-sol} fails for $j=0$. Claim that for all $j\ge0$ that violate \eqref{ls-sol}, it holds that
\begin{equation}\label{lwbd-sol-ak}
\theta^{2j}\ge\min\{6(1-\eta),2\}\epsilon_H(L^F_H)^{-1}\|d^t\|^{-1}.
\end{equation}
Indeed, suppose that \eqref{ls-sol} is violated by some $j \ge 0$. We now show that \eqref{lwbd-sol-ak} holds for such $j$ by considering two separate cases below.

Case 1) $F(x^t+\theta^jd^t)>F(x^t)$. Let $\phi(\alpha)=F(x^t+\alpha d^t)$. Then $\phi(\theta^j)>\phi(0)$. Also, since $d^t\neq0$, by \eqref{SOL-ppty-1} and \eqref{SOL-ppty-3}, one has 
\[
\phi^\prime(0)  =\nabla F(x^t)^Td^t = -(d^t)^T(\nabla^2 F(x^t)+2\epsilon_HI)d^t 
 \le-\epsilon_H\|d^t\|^2< 0.
\]
Using these, we can observe that there exists a local minimizer $\alpha^*\in(0,\theta^j)$ of $\phi$ such that $\phi^\prime(\alpha^*)=\nabla F(x^t+\alpha^*d^t)^Td^t=0$ and $\phi(\alpha^*)<\phi(0)$, which implies that $F(x^t+\alpha^*d^t)< F(x^t)\le F(u^0)$. Hence, \eqref{apx-nxt-grad} holds for $x=x^t$ and $y=x^t+\alpha^*d^t$. Using this, $0<\alpha^*<\theta^j\le1$ and $\nabla F(x^t+\alpha^*d^t)^Td^t=0$, we obtain
\[
\begin{array}{l}
\frac{(\alpha^*)^2L_H^F}{2}\|d^t\|^3\overset{\eqref{apx-nxt-grad}}{\ge}\|d^t\|\|\nabla F(x^t+\alpha^*d^t)-\nabla F(x^t)-\alpha^*\nabla^2 F(x^t)d^t\|\\[6pt]
\ge(d^t)^T(\nabla F(x^t+\alpha^*d^t)-\nabla F(x^t)-\alpha^*\nabla^2 F(x^t)d^t)=-(d^t)^T\nabla F(x^t)-\alpha^*(d^t)^T\nabla^2 F(x^t)d^t\\[6pt]
\overset{\eqref{SOL-ppty-3}}{=}(1-\alpha^*)(d^t)^T(\nabla^2 F(x^t)+2\epsilon_HI)d^t +2 \alpha^*\epsilon_H\|d^t\|^2\overset{\eqref{SOL-ppty-1}}{\ge} (1+\alpha^*)\epsilon_H\|d^t\|^2\ge \epsilon_H \|d^t\|^2,
\end{array}
\]
which along with $d^t\neq 0$ implies that $(\alpha^*)^2\ge 2\epsilon_H(L_H^F)^{-1}\|d^t\|^{-1}$. Using this and $\theta^{j}>\alpha^*$, we conclude that \eqref{lwbd-sol-ak} holds in this case.

Case 2) $F(x^t+\theta^jd^t)\le F(x^t)$. This together with $F(x^t)\le F(u^0)$ implies that
\eqref{desc-ineq} holds for $x=x^t$ and $y=x^t+\theta^jd^t$. Then, because $j$ violates \eqref{ls-sol}, we obtain
%By this and the fact that $j$ violates \eqref{ls-sol}, we obtain that
\beqa
&&-\eta\epsilon_H\theta^{2j}\|d^t\|^2\le F(x^t+\theta^jd^t)-F(x^t)\overset{\eqref{desc-ineq}}{\le} \theta^j \nabla F(x^t)^Td^t + \frac{\theta^{2j}}{2}(d^t)^T\nabla^2 F(x^t) d^t + \frac{L_H^F}{6}\theta^{3j}\|d^t\|^3 \nn \\
&&\overset{\eqref{SOL-ppty-3}}{=}-\theta^j (d^t)^T(\nabla^2 F(x^t) +2\epsilon_H I)d^t + \frac{\theta^{2j}}{2}(d^t)^T\nabla^2 F(x^t) d^t + \frac{L_H^F}{6}\theta^{3j}\|d^t\|^3 \nn \\
&&=-\theta^j\left(1-\frac{\theta^j}{2}\right)(d^t)^T(\nabla^2 F(x^t) +2\epsilon_H I)d^t - \theta^{2j} \epsilon_H\|d^t\|^2 + \frac{L_H^F}{6}\theta^{3j}\|d^t\|^3 \nn \\
&&\overset{\eqref{SOL-ppty-1}}{\le} -\theta^j\left(1-\frac{\theta^j}{2}\right) \epsilon_H\|d^t\|^2 - \theta^{2j}\epsilon_H\|d^t\|^2 + \frac{L_H^F}{6}\theta^{3j}\|d^t\|^3 \le -\theta^j \epsilon_H\|d^t\|^2 + \frac{L_H^F}{6}\theta^{3j}\|d^t\|^3. \label{ineq:desc-ls-sol}
\eeqa
Recall that $d^t \neq 0$. Dividing both sides of \eqref{ineq:desc-ls-sol} by $L_H^F\theta^j\|d^t\|^3/6$ and using $\eta, \theta\in(0,1)$, we obtain that 
\[
\theta^{2j}\ge 6(1-\theta^j\eta)\epsilon_H(L_H^F)^{-1}\|d^t\|^{-1}\ge6(1-\eta)\epsilon_H(L_H^F)^{-1}\|d^t\|^{-1}.
\] 
 Hence, \eqref{lwbd-sol-ak} also holds in this case.

Combining the above two cases, we conclude that  \eqref{lwbd-sol-ak} holds for any $j\ge0$ that violates \eqref{ls-sol}.
By this and $\theta\in(0,1)$, one can see that all $j\ge0$ that violate \eqref{ls-sol} must be bounded above. It then follows that the step length $\alpha_t$ associated with \eqref{ls-sol} is well-defined. We next prove \eqref{lwbd-ak-sol}. Observe from the definition of $j_t$ in Algorithm~\ref{alg:NCG} that $j=j_t-1$ violates \eqref{ls-sol} and hence \eqref{lwbd-sol-ak} holds for $j=j_t-1$. Then, by \eqref{lwbd-sol-ak} with $j=j_t-1$ and $\alpha_t = \theta^{j_t}$, one has
\begin{equation}\label{lwbd-sol-ak-1}
\alpha_t = \theta^{j_t} \ge\sqrt{\min\{6(1-\eta),2\}\epsilon_H(L^F_H)^{-1}} \ \theta\|d^t\|^{-1/2},
\end{equation}
which,  along with \eqref{SOL-ppty-2} and $\|\nabla F(x^t)\|\le U^F_g$, implies \eqref{lwbd-ak-sol}. This proves statement (i).

We next prove statement (ii) %, particularly,  \eqref{suff-desc-sol}
by considering two separate cases below.

Case 1) $\alpha_t=1$. By this, one knows that \eqref{ls-sol} holds for $j=0$. It then follows that $F(x^t+d^t)\le F(x^t)\le F(u^0)$, which implies that \eqref{apx-nxt-grad} holds for $x=x^t$ and $y=x^t+d^t$. By this and \eqref{SOL-ppty-4}, one has
\[
\begin{array}{lcl}
%\|\nabla F(x^{t+1})\|=\|\nabla F(x^{t}+d^t)-\nabla F(x^t)+\nabla F(x^t)\|\\[4pt]
\|\nabla F(x^{t+1})\|=\|\nabla F(x^{t}+d^t)\|
&\le&\|\nabla F(x^t+d^t)-\nabla F(x^t)-\nabla^2 F(x^t)d^t\| \\[4pt]
&&+\|(\nabla^2 F(x^t)+2\epsilon_HI)d^t+\nabla F(x^t)\|+2\epsilon_H\|d^t\|\\[4pt]
&\le& \frac{L_H^F}{2}\|d^t\|^2 + \frac{4+\zeta}{2}\epsilon_H\|d^t\|,
\end{array}
\]
where the last inequality follows from \eqref{apx-nxt-grad} and \eqref{SOL-ppty-4}. Solving the above inequality for $\|d^t\|$ and using the fact that $\|d^t\|>0$, we obtain that
\[
\begin{array}{rcll}
\|d^t\|&\ge&\frac{-(4+\zeta)\epsilon_H + \sqrt{(4+\zeta)^2\epsilon_H^2+8L_H^F\|\nabla F(x^{t+1})\|}}{2L_H^F}\ \ge\
\frac{-(4+\zeta)\epsilon_H + \sqrt{(4+\zeta)^2\epsilon_H^2+8L_H^F\epsilon_H^2}}{2L_H^F}\min\{\|\nabla F(x^{t+1})\|/\epsilon_H^2,1\}\\[6pt]
&=&\frac{4}{4+\zeta+\sqrt{(4+\zeta)^2+8L_H^F}}\min\{\|\nabla F(x^{t+1})\|/\epsilon_H,\epsilon_H\},
\end{array}
\]
where the second inequality follows from the inequality $-a+\sqrt{a^2+bs}\ge(-a+\sqrt{a^2+b})\min\{s,1\}$ for all $a,b,s\ge0$,
%which can be seen to hold by performing rationalization to the terms $-a+\sqrt{a^2+b}$ and $-a+\sqrt{a^2+bs}$.
which can be verified by performing a rationalization to the terms $-a+\sqrt{a^2+b}$ and $-a+\sqrt{a^2+bs}$, respectively.
By this, $\alpha_t=1$, \eqref{ls-sol} and \eqref{csol}, one can see that \eqref{suff-desc-sol} holds.

Case 2) $\alpha_t<1$.
It then follows that $j=0$ violates \eqref{ls-sol} and hence \eqref{lwbd-sol-ak} holds for $j=0$.
Now, letting $j=0$ in \eqref{lwbd-sol-ak}, we obtain that $\|d^t\|\ge \min\{6(1-\eta),2\}\epsilon_H/L_H^F$,
 which together with \eqref{ls-sol} and \eqref{lwbd-sol-ak-1} implies that
\[
F(x^t)-F(x^{t+1}) \ge \eta \epsilon_H\theta^{2j_t}\|d^t\|^2 \ge \eta\frac{\min\{6(1-\eta),2\}\epsilon_H^2}{L_H^F}\theta^2\|d^t\|\ge \eta\left[\frac{\min\{6(1-\eta),2\}\theta}{L_H^F}\right]^2\epsilon_H^3.
\]
By this and \eqref{csol}, one can see that \eqref{suff-desc-sol} also holds in this case.
\end{proof}

\begin{lemma}\label{lem:nc}
Suppose that Assumption \ref{asp:NCG-cmplxity} holds and the direction $d^t$ results from  either the output $d$ of Algorithm~\ref{alg:capped-CG} with d$\_$type=NC or the output $v$ of Algorithm~\ref{pro:meo} at some iteration $t$ of Algorithm~\ref{alg:NCG}.
%\begin{equation}\label{cnc}
%c_{\rm nc} = \frac{\eta}{2} \min\left\{1,\left[\frac{3(1-\eta)\theta}{L_H^F}\right]^2\right\}.
%\end{equation}
Let  $c_{\rm nc}$ be defined in \eqref{cnc}.
%\begin{equation}\label{cnc}
%c_{\rm nc} := \frac{\eta}{2} \min\left\{1,\left[\frac{\min\{3(1-\eta),1\}\theta}{L_H^F}\right]^2\right\}.
%\end{equation}
Then the following statements hold.
\begin{enumerate}[{\rm (i)}]
\item The step length $\alpha_t$ is well-defined, and $\alpha_t\ge \min\{1,\theta/L_H^F,3(1-\eta)\theta/L_H^F\}$.
%\item If $d^t$ results from the output $d$ of Algorithm~\ref{alg:capped-CG} with d$\_$type=NC, then the next iterate $x^{t+1}=x^t+\alpha_td^t$ satisfies $F(x^t)-F(x^{t+1})\ge c_{\rm nc}\epsilon_H^3$.
%\item If $d^t$ { results from} the output $v$ of Algorithm~\ref{pro:meo}, then the next iterate $x^{t+1}=x^t+\alpha_td^t$ satisfies $F(x^t)-F(x^{t+1})\ge c_{\rm nc}\epsilon_H^3/8$.
\item The next iterate $x^{t+1}=x^t+\alpha_td^t$ satisfies $F(x^t)-F(x^{t+1})\ge c_{\rm nc}\epsilon_H^3$.
\end{enumerate}
\end{lemma}

\begin{proof}
Observe that $F$ is descent along the iterates (whenever well-defined) generated by Algorithm~\ref{alg:NCG}. Using this and $x^0=u^0$, we have $F(x^t)\le F(u^0)$.
By the assumption on $d^t$, one can see from Algorithm \ref{alg:NCG} that
%$d^t$ is given in \eqref{dk-nc} or \eqref{dk-2nd-nc}. Now, notice that the (negative curvature) direction $v$ returned from Algorithm~\ref{pro:meo} satisfies $\|v\|=1$. This observation (for $d^t$ in \eqref{dk-2nd-nc}) together with  Lemma~\ref{lem:SOL-NC-ppty}(ii) (for $d^t$ in \eqref{dk-nc}) shows that $d^t$ must satisfy
$d^t$ is a negative curvature direction given in \eqref{dk-nc} or \eqref{dk-2nd-nc}. Also, notice that the vector $v$ returned from Algorithm~\ref{pro:meo} satisfies $\|v\|=1$. By these, Lemma~\ref{lem:SOL-NC-ppty}(ii), \eqref{dk-nc} and \eqref{dk-2nd-nc}, one can observe that
\begin{equation}\label{dk-Hk-dk3}
\nabla F(x^t)^Td^t\le 0, \quad (d^t)^T\nabla^2 F(x^t)d^t=-\|d^t\|^3<0.
\end{equation}

We first prove statement (i). If \eqref{ls-nc} holds for $j=0$, then $\alpha_t=1$, which clearly implies that $\alpha_t\ge\min\{1,\theta/L_H^F,3(1-\eta)\theta/L_H^F\}$. We now suppose that \eqref{ls-nc} fails for $j=0$. Claim that for all $j\ge0$ that violate \eqref{ls-nc}, it holds that
\begin{equation}\label{lwbd-at-nc}
\theta^j\ge \min\{1/L_H^F,3(1-\eta)/L_H^F\}.
\end{equation}
Indeed, suppose that \eqref{ls-nc} is violated by some $j \ge 0$. We now show that \eqref{lwbd-at-nc} holds for such $j$ by considering two separate cases below.

Case 1) $F(x^t+\theta^jd^t)>F(x^t)$. Let $\phi(\alpha)=F(x^t+\alpha d^t)$. Then $\phi(\theta^j)>\phi(0)$. Also, by  \eqref{dk-Hk-dk3}, one has 
\[
\phi^\prime(0)=\nabla F(x^t)^Td^t\le 0, \quad \phi^{\prime\prime}(0)=(d^t)^T\nabla^2 F(x^t)d^t<0.
\]
 Using these, we can observe that there exists a local minimizer $\alpha^*\in(0,\theta^j)$ of $\phi$ such that $\phi(\alpha^*)<\phi(0)$, namely,  $F(x^t+\alpha^*d^t)< F(x^t)$. By the second-order optimality condition of $\phi$ at $\alpha^*$, one has $\phi^{\prime\prime}(\alpha^*)=(d^t)^T\nabla^2 F(x^t+\alpha^*d^t)d^t\ge 0$. Since $F(x^t+\alpha^*d^t)<F(x^t)\le F(u^0)$, it follows that \eqref{F-Hess-Lip} holds for $x=x^t$ and $y=x^t+\alpha^*d^t$. Using this, the second relation in \eqref{dk-Hk-dk3} and $(d^t)^T\nabla^2 F(x^t+\alpha^*d^t)d^t\ge0$, we obtain that
in \eqref{dk-Hk-dk3} and $(d^t)^T\nabla^2 F(x^t+\alpha^*d^t)d^t\ge0$, we obtain that
\beqa
L_H^F\alpha^*\|d^t\|^3 &\overset{\eqref{F-Hess-Lip}}{\ge}&\|d^t\|^2\|\nabla^2 F(x^t+\alpha^*d^t)-\nabla^2 F(x^t)\| \ge (d^t)^T(\nabla^2 F(x^t+\alpha^*d^t)-\nabla^2 F(x^t))d^t \nn \\
&\ge& -(d^t)^T\nabla^2 F(x^t)d^t=\|d^t\|^3. \label{lwbd-dt-nc-j1}
\eeqa
Recall from \eqref{dk-Hk-dk3} that $d^t\neq 0$. It then follows from \eqref{lwbd-dt-nc-j1} that $\alpha^*\ge 1/L_H^F$, which along with $\theta^j>\alpha^*$ implies that $ \theta^j> 1/L_H^F$. Hence, \eqref{lwbd-at-nc} holds in this case.

Case 2) $F(x^t+\theta^jd^t)\le F(x^t)$. It follows from this and $F(x^t)\le F(u^0)$ that \eqref{desc-ineq} holds for $x=x^t$ and $y=x^t+\theta^jd^t$. By this and the fact that $j$ violates \eqref{ls-nc}, one has
\begin{equation*}\label{lwbd-dt-nc}
\begin{array}{lcl}
-\frac{\eta}{2}\theta^{2j}\|d^t\|^3 &\le& F(x^t+\theta^j d^t) - F(x^t) \overset{\eqref{desc-ineq}}{\le} \theta^j \nabla F(x^t)^Td^t + \frac{\theta^{2j}}{2}(d^t)^T\nabla^2 F(x^t) d^t + \frac{L_H^F}{6}\theta^{3j}\|d^t\|^3\\[6pt]
&\overset{\eqref{dk-Hk-dk3}}{\le}& -\frac{\theta^{2j}}{2}\|d^t\|^3 + \frac{L_H^F}{6}\theta^{3j}\|d^t\|^3,
\end{array}
\end{equation*}
which together with $d^t\neq 0$ implies that $\theta^j\ge 3(1-\eta)/L_H^F$. Hence, \eqref{lwbd-at-nc} also holds  in this case.

Combining the above two cases, we conclude that \eqref{lwbd-at-nc} holds for any $j\ge0$ that violates \eqref{ls-nc}. By this and $\theta\in(0,1)$, one can see that all $j\ge0$ that violate \eqref{ls-nc} must be bounded above. It then follows that the step length $\alpha_t$ associated with \eqref{ls-nc} is well-defined. We next derive a lower bound for $\alpha_t$. Notice from the definition of $j_t$ in Algorithm~\ref{alg:NCG} that $j=j_t-1$ violates \eqref{ls-nc} and hence \eqref{lwbd-at-nc} holds for $j=j_t-1$. Then, by \eqref{lwbd-at-nc} with $j=j_t-1$ and $\alpha_t = \theta^{j_t}$, one has $\alpha_t=\theta^{j_t} \ge \min\{\theta/L_H^F,3(1-\eta)\theta/L_H^F\}$, which immediately yields $\alpha_t\ge \min\{1,\theta/L_H^F,3(1-\eta)\theta/L_H^F\}$ as desired.

We next prove statement (ii) by considering two separate cases below.

Case 1) $d^t$ results from the output $d$ of Algorithm~\ref{alg:capped-CG} with d$\_$type=NC. It then follows from  \eqref{NC-ppty} that $\|d^t\|\ge\epsilon_H$. 
%{ This together with item (i) and \eqref{ls-nc} implies (ii).}
This together with  \eqref{ls-nc} and statement (i) implies that statement (ii) holds.

Case 2) $d^t$ results from the output $v$ of Algorithm~\ref{pro:meo}. Notice from
Algorithm~\ref{pro:meo} that $\|v\|=1$ and $v^T\nabla^2F(x^t)v\le-\epsilon_H/2$, which along with \eqref{dk-2nd-nc} yields $\|d^t\|\ge\epsilon_H/2$. By this, \eqref{ls-nc} and statement (i), one can see that statement (ii) again holds.
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:NCG-iter-oper-cmplxity}]
For notational convenience, we let $\{x^t\}_{t\in\bT}$ denote all the iterates generated by Algorithm~\ref{alg:NCG}, where $\bT$ is a set of consecutive nonnegative integers starting from $0$. Notice that $F$ is descent along the iterates generated by Algorithm~\ref{alg:NCG}, which together with $x^0=u^0$ implies that $x^t\in\{x:F(x)\le F(u^0)\}$. It then follows from
\eqref{lwbd-Hgupbd} that $\|\nabla^2 F(x^t)\|\le U^F_H$ holds for all $t\in\bT$.

(i) Suppose for contradiction that the total number of calls of Algorithm~\ref{pro:meo} in Algorithm~\ref{alg:NCG} is more than $T_2$. Notice from Algorithm~\ref{alg:NCG} and Lemma~\ref{lem:nc}(ii) that each of these calls, except the last one, returns a sufficiently negative curvature direction, and each of them results in a reduction on $F$ of at least $c_{\rm nc} \epsilon_H^3$. Hence, 
\[
T_2 c_{\rm nc} \epsilon_H^3 \le \sum_{t\in\bT} [F(x^t)-F(x^{t+1})] \le F(x^0)-\Fl = \Fh-\Fl,
\]
which contradicts the definition of $T_2$ given in \eqref{T1}. Hence, statement (i) of Theorem \ref{thm:NCG-iter-oper-cmplxity} holds.

(ii) Suppose for contradiction that the total number of calls of Algorithm~\ref{alg:capped-CG} in Algorithm~\ref{alg:NCG} is more than $T_1$. Observe that if Algorithm~\ref{alg:capped-CG} is called at some iteration $t$ and generates the next iterate $x^{t+1}$ satisfying $\|\nabla F(x^{t+1})\|\le\epsilon_g$, then Algorithm~\ref{pro:meo} must be called at the next iteration $t+1$. In view of this and statement (i) of Theorem \ref{thm:NCG-iter-oper-cmplxity}, we see that the total number of such iterations $t$ is at most $T_2$. Hence, the total number of iterations $t$ of Algorithm~\ref{alg:NCG} at which Algorithm~\ref{alg:capped-CG} is called and generates the next iterate $x^{t+1}$ satisfying $\|\nabla F(x^{t+1})\|>\epsilon_g$ is at least $T_1-T_2+1$. Moreover, for each of such iterations $t$, we observe from Lemmas~\ref{lem:sol}(ii) and \ref{lem:nc}(ii) that $F(x^t)-F(x^{t+1})\ge \min\{c_{\rm sol},c_{\rm nc}\}\min\{\epsilon_g^2\epsilon_H^{-1},\epsilon_H^3\}$. It then follows that 
\[
(T_1-T_2+1) \min\{c_{\rm sol},c_{\rm nc}\}\min\{\epsilon_g^2\epsilon_H^{-1},\epsilon_H^3\} \le \sum_{t\in\bT}[F(x^t)-F(x^{t+1})]\le \Fh-\Fl,
\]
which contradicts the definition of $T_1$ and $T_2$ given in \eqref{T1}. Hence, statement (ii) of Theorem \ref{thm:NCG-iter-oper-cmplxity} holds.

(iii) Notice that either Algorithm~\ref{alg:capped-CG} or \ref{pro:meo} is called at each iteration of Algorithm~\ref{alg:NCG}. It follows from this and statements (i) and (ii) of Theorem \ref{thm:NCG-iter-oper-cmplxity} that the total number of iterations of Algorithm~\ref{alg:NCG} is at most $T_1+T_2$. In addition, the relation \eqref{NCG-iter} follows from \eqref{csol}, \eqref{cnc} and \eqref{T1}. One can also observe that the output $x^t$ of Algorithm~\ref{alg:NCG} satisfies $\|\nabla F(x^t)\|\le \epsilon_g$ deterministically and $\lambda_{\min}(\nabla^2F(x^t))\ge-\epsilon_H$ with probability at least $1-\delta$ for some $0 \le t \le T_1+T_2$, where the latter part is due to
Algorithm~\ref{pro:meo}. This completes the proof of statement (ii) of Theorem \ref{thm:NCG-iter-oper-cmplxity}.

(iv) By Theorem~\ref{lem:capped-CG} with $(H,\varepsilon)=(\nabla^2 F(x^t),\epsilon_H)$ and the fact that $\|\nabla^2 F(x^t)\|\le U^F_H$, one can observe that  the number of Hessian-vector products required by each call of Algorithm~\ref{alg:capped-CG} with input $U = 0$ is at most $\widetilde{\cO}(\min\{n,(U_H^F/\epsilon_H)^{1/2}\})$. In addition, by Theorem~\ref{rand-Lanczos} with $(H,\varepsilon)=(\nabla^2 F(x^t),\epsilon_H)$, $\|\nabla^2 F(x^t)\|\le U^F_H$, and the fact that each iteration of the Lanczos method requires only one matrix-vector product, one can observe that the number of Hessian-vector products required by each call of Algorithm~\ref{pro:meo} is also at most $\widetilde{\cO}(\min\{n,(U_H^F/\epsilon_H)^{1/2}\})$. Based on these observations and statement (iii) of Theorem \ref{thm:NCG-iter-oper-cmplxity}, we see that  statement (iv) of this theorem holds.
\end{proof}

Recall from Assumption~\ref{asp:lowbd-knownfeas}(a) that $\|c(z_{\epsilon_1})\|\le\epsilon_1/2<1$. By virtue of this, \eqref{lbd} and the definition of $\tilde{c}$ in
\eqref{model:equa-cnstr-pert},
we obtain that
\begin{equation}\label{ineq:p-lowbd}
f(x)+\gamma\|\tilde{c}(x)\|^2 \ge f(x)+ \gamma\|c(x)\|^2/2 - \gamma \|c(z_{\epsilon_1})\|^2 \ge \fl - \gamma,\quad \forall x\in\bR^n.
\end{equation}


\begin{lemma}\label{tech-1}
Suppose that Assumption \ref{asp:lowbd-knownfeas} holds. Let $\gamma$, $\fh$ and $\fl$ be given in Assumption \ref{asp:lowbd-knownfeas}.  Assume that $\rho>2\gamma$, $\lambda\in\bR^m$, and $x\in\bR^n$ satisfy
\begin{equation}\label{AL-upperbound}
\widetilde{\cL}(x,\lambda;\rho)\le \fh,
\end{equation}
%where $\fh=f(x^{\feas})$.
%where $\gamma$ and $\fh$ are given in Assumption \ref{asp:lowbd-knownfeas}.
where $\widetilde{\cL}$ is defined in \eqref{tL-tc}.
Then the following statements hold.
\begin{enumerate}[{\rm (i)}]
\item $f(x)\le \fh+\|\lambda\|^2/(2\rho)$.
\item $\|\tilde{c}(x)\|\le\sqrt{2(\fh-\fl+\gamma)/(\rho-2\gamma)+\|\lambda\|^2/(\rho-2\gamma)^2}+\|\lambda\|/(\rho-2\gamma)$.
\item If $\rho\ge\|\lambda\|^2/(2\tdf)$ for some $\tdf>0$, then $f(x)\le \fh+\tdf$.
\item If
%\begin{equation}\label{bound-rho-deltac}
%\rho\ge\frac{2(\fh-\fl)}{\delta_c^2}+\frac{2\|\lambda\|}{\delta_c}+\gamma
%\end{equation}
\begin{equation}\label{bound-rho-deltac}
\rho\ge 2(\fh-\fl+\gamma)\tdc^{-2}+ 2\|\lambda\|\tdc^{-1}+2\gamma
\end{equation}
for some $\tdc>0$, then $\|\tilde{c}(x)\|\le\tdc$.
\end{enumerate}
\end{lemma}

\begin{proof}
(i) It follows from
%{ the definition of { $\widetilde{\cL}$} in} \eqref{tL-tc} and \eqref{AL-upperbound}
 \eqref{AL-upperbound} and the definition of $\widetilde{\cL}$ in \eqref{tL-tc}
that
\[
\textstyle
\fh\ge f(x)+\lambda^T \tilde{c}(x)+\frac{\rho}{2}\|\tilde{c}(x)\|^2 = f(x)+\frac{\rho}{2}\left\|\tilde{c}(x)+\frac{\lambda}{\rho}\right\|^2-\frac{\|\lambda\|^2}{2\rho} \ge f(x)-\frac{\|\lambda\|^2}{2\rho}.
\]
Hence, statement (i) holds.

(ii) In view of \eqref{ineq:p-lowbd} and \eqref{AL-upperbound}, one has
\begin{equation*}\label{ineq:bound-cx-step1}
\begin{array}{l}
\fh\overset{\eqref{AL-upperbound}}{\ge}f(x)+\lambda^T\tilde{c}(x)+\frac{\rho}{2}\|\tilde{c}(x)\|^2=f(x)+\gamma\|\tilde{c}(x)\|^2
+\frac{\rho-2\gamma}{2}\left\|\tilde{c}(x)+\frac{\lambda}{\rho-2\gamma}\right\|^2-\frac{\|\lambda\|^2}{2(\rho-2\gamma)}\\[2pt]
\ \ \ \ \overset{\eqref{ineq:p-lowbd}}{\ge}\fl- \gamma+\frac{\rho-2\gamma}{2}\left\|\tilde{c}(x)+\frac{\lambda}{\rho-2\gamma}\right\|^2-\frac{\|\lambda\|^2}{2(\rho-2\gamma)}.
\end{array}
\end{equation*}
It then follows that $\left\|\tilde{c}(x)+\frac{\lambda}{\rho-2\gamma}\right\|\le\sqrt{\frac{2(\fh-\fl+\gamma)}{\rho-2\gamma}+\frac{\|\lambda\|^2}{(\rho-2\gamma)^2}}$,  which implies that statement (ii) holds.

(iii) Statement (iii) immediately follows from statement (i) and $\rho\ge\|\lambda\|^2/(2\tdf)$.

(iv) Suppose that \eqref{bound-rho-deltac} holds. Multiplying both sides of \eqref{bound-rho-deltac} by $\tdc^{2}$ and rearranging the terms, we have
\[
(\rho-2\gamma)\tdc^2-2\|\lambda\|\tdc-2(\fh-\fl+\gamma)\ge0.
\]
Recall that $\rho>2\gamma$ and $\tdc>0$. Solving this inequality for $\tdc$ yields 
\[
\tdc\ge\sqrt{2(\fh-\fl+\gamma)/(\rho-2\gamma)+\|\lambda\|^2/(\rho-2\gamma)^2}+\|\lambda\|/(\rho-2\gamma),
\]
which along with statement (ii) implies that $\|\tilde{c}(x)\|\le\tdc$. Hence, statement (iv) holds.
\end{proof}

\begin{proof}[Proof of Lemma \ref{lem:level-set-augmented-lagrangian-func}]
(i) Let $x$ be any point such that $\widetilde{\cL}(x,\lambda^k;\rho_k)\le \widetilde{\cL}(x^{k}_{\init},\lambda^k;\rho_k)$. It then follows from \eqref{L-xinit} that $\widetilde{\cL}(x,\lambda^k;\rho_k) \le \fh$. By this, $\|\lambda^k\|\le\Lambda$, $\rho_k \ge \rho_0>2\gamma$, $\delta_{f,1} \le \bdelta_f$, $\delta_{c,1} \le \bdelta_c$, and Lemma \ref{tech-1} with $(\lambda,\rho)=(\lambda^k,\rho_k)$,  one has 
\begin{align}
f(x) & \le \fh+ \|\lambda^k\|^2/(2\rho_k)\le \fh+ \Lambda^2/(2\rho_0)=\fh+\delta_{f,1} \le \fh+\bdelta_f, \nonumber \\
\textstyle\|\tilde{c}(x)\|&\textstyle\le\sqrt{\frac{2(\fh-\fl+\gamma)}{\rho_k-2\gamma}+\frac{\|\lambda^k\|^2}{(\rho_k-2\gamma)^2}}+\frac{\|\lambda^k\|}{\rho_k-2\gamma}\le\sqrt{\frac{2(\fh-\fl+\gamma)}{\rho_0-2\gamma}+\frac{\Lambda^2}{(\rho_0-2\gamma)^2}}+\frac{\Lambda}{\rho_0-2\gamma}=\delta_{c,1} \le \bdelta_c. \label{ineq:feasible-bd}
\end{align}
%\begin{eqnarray}
%&f(x)\le \fh+\frac{\|\lambda^k\|^2}{2\rho_k}\le \fh+\frac{\Lambda^2}{2\rho_0}=\fh+\delta_{f,1} \le \fh+\bdelta_f,\nn \\
%&\|\tilde{c}(x)\|\le\sqrt{\frac{2(\fh-\fl+\gamma)}{\rho_k-2\gamma}+\frac{\|\lambda^k\|^2}{(\rho_k-2\gamma)^2}}+\frac{\|\lambda^k\|}{\rho_k-2\gamma}\le\sqrt{\frac{2(\fh-\fl+\gamma)}{\rho_0-2\gamma}+\frac{\Lambda^2}{(\rho_0-2\gamma)^2}}+\frac{\Lambda}{\rho_0-2\gamma}=\delta_{c,1} \le \bdelta_c.\label{ineq:feasible-bd}
%\end{eqnarray}
Also, recall from the definition of $\tilde{c}$ in \eqref{model:equa-cnstr-pert}
and $\|c(z_{\epsilon_1})\|\le1$ that $\|c(x)\|\le1+\|\tilde{c}(x)\|$. This together with the above inequalities and \eqref{nearly-feas-level-set} implies $x\in\cS(\delta_{f},\delta_{c})$. Hence, statement (i) of Lemma \ref{lem:level-set-augmented-lagrangian-func} holds.

(ii) Note that $\inf\limits_{x\in\bR^n} \widetilde{\cL}(x,\lambda^k;\rho_k)=\inf\limits_{x\in\bR^n}\{\widetilde{\cL}(x,\lambda^k;\rho_k):\widetilde{\cL}(x,\lambda^k;\rho_k) \le \widetilde{\cL}(x^{k}_{\init},\lambda^k;\rho_k)\}$. Consequently, to prove statement (ii) of Lemma \ref{lem:level-set-augmented-lagrangian-func}, it suffices to show that
\begin{equation} \label{L-lwbd}
\inf\limits_{x\in\bR^n}\{\widetilde{\cL}(x,\lambda^k;\rho_k): \widetilde{\cL}(x,\lambda^k;\rho_k) \le \widetilde{\cL}(x^{k}_{\init},\lambda^k;\rho_k)\} \ge\fl - \gamma-\Lambda\bdelta_c.
\end{equation}
To this end, let $x$ be any point satisfying $\widetilde{\cL}(x,\lambda^k;\rho_k) \le\widetilde{\cL}(x^{k}_{\init},\lambda^k;\rho_k)$. We then know from \eqref{ineq:feasible-bd} that $\|\tilde{c}(x)\|\le\bdelta_c$. By this, $\|\lambda^k\|\le\Lambda$, $\rho_k>2\gamma$, and \eqref{ineq:p-lowbd}, one has
\begin{equation*}\label{ineq:lowerbound-ALfunc} 
\begin{array}{l}
\widetilde{\cL}(x,\lambda^k;\rho_k) %= f(x)+(\lambda^k)^T\tilde{c}(x)+\frac{\rho_k}{2}\|\tilde{c}(x)\|^2\\[4pt]
=f(x)+\gamma\|\tilde{c}(x)\|^2+(\lambda^k)^T\tilde{c}(x)+\frac{\rho_k-2\gamma}{2}\|\tilde{c}(x)\|^2\\[4pt]
\ge f(x)+\gamma\|\tilde{c}(x)\|^2 - \Lambda\|\tilde{c}(x)\| \ge\fl - \gamma-\Lambda\bdelta_c,
\end{array}
\end{equation*}
and hence \eqref{L-lwbd} holds as desired.
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:output-alg1}]
Suppose that Algorithm \ref{alg:2nd-order-AL-nonconvex} terminates at some iteration $k$, that is, $\tau_k^g\le\epsilon_1$, $\tau_k^H\le\epsilon_2$, and $\|c(x^{k+1})\|\le\epsilon_1$ hold. Then, by $\tau_k^g\le\epsilon_1$, $\tilde{\lambda}^{k+1}=\lambda^k+\rho_k\tilde{c}(x^{k+1})$, $\nabla \tilde{c}=\nabla c$ and the second relation in \eqref{algstop:1st-order}, one has 
 \begin{align*}
\|\nabla f(x^{k+1})+\nabla c(x^{k+1})\tilde{\lambda}^{k+1}\| &=\|\nabla f(x^{k+1})+\nabla \tilde{c}(x^{k+1})(\lambda^k+\rho_k \tilde{c}(x^{k+1}))\| \\ 
&=\|\nabla_x\widetilde{\cL}(x^{k+1},\lambda^k;\rho_k)\|\le \tau_k^g \le \epsilon_1.
\end{align*} 
 Hence, $(x^{k+1},\tilde{\lambda}^{k+1})$ satisfies the first relation in \eqref{optcond:1st-equa-cnstr}. In addition, by \eqref{algstop:2nd-order} and $\tau_k^H\le\epsilon_2$, one can show that $\lambda_{\min}(\nabla^2_{xx}\widetilde{\cL}(x^{k+1},\lambda^k;\rho_k))\ge-\epsilon_2$ with probability at least $1-\delta$, which leads to $d^T\nabla^2_{xx}\widetilde{\cL}(x^{k+1},\lambda^k;\rho_k)d \ge -\epsilon_2\|d\|^2$ for all $d\in\bR^n$ with probability at least $1-\delta$.  Using this, $\tilde{\lambda}^{k+1}=\lambda^k+\rho_k\tilde{c}(x^{k+1})$, $\nabla \tilde{c} = \nabla c$, and $\nabla^2 \tilde{c}_i=\nabla^2 c_i$ for $1\le i\le m$, we see that with probability at least $1-\delta$, it holds that 
%$d^T (\nabla^2 f(x^{k+1})+\sum_{i=1}^m\tilde{\lambda}_i^{k+1}\nabla^2c_i(x^{k+1})+\rho_k\nabla c(x^{k+1})\nabla c(x^{k+1})^T )d\ge -\epsilon_2\|d\|^2$ for all $d\in\bR^n$},
\[
d^T\left(\nabla^2 f(x^{k+1})+\sum_{i=1}^m\tilde{\lambda}_i^{k+1}\nabla^2c_i(x^{k+1})+\rho_k\nabla c(x^{k+1})\nabla c(x^{k+1})^T\right)d\ge -\epsilon_2\|d\|^2 \ \  \forall d\in\bR^n,
\]
which implies $d^T(\nabla^2 f(x^{k+1})+\sum_{i=1}^m\tilde{\lambda}_i^{k+1}\nabla^2 c_i(x^{k+1}))d\ge -\epsilon_2\|d\|^2$ for all $d\in \cC(x^{k+1})$, where $\cC(\cdot)$ is defined in \eqref{def:critical-cone}. Hence, $(x^{k+1},\tilde{\lambda}^{k+1})$ satisfies \eqref{optcond:2nd-equa-cnstr} with probability at least $1-\delta$. Combining these with $\|c(x^{k+1})\|\le\epsilon_1$, we conclude that $x^{k+1}$ is a deterministic $\epsilon_1$-FOSP of \eqref{model:equa-cnstr} and an $(\epsilon_1,\epsilon_2)$-SOSP of \eqref{model:equa-cnstr} with probability at least $1-\delta$. Hence, Theorem \ref{thm:output-alg1} holds.
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:out-itr-cmplxity-1}]
It follows from \eqref{def:delta0c-rhobar1} that ${\rho}_{\epsilon_1}\ge 2\rho_0$.
By this, one has
\begin{equation}\label{T-epsilong}
K_{\epsilon_1} \ \overset{\eqref{T-epsilon-g}}{=} \ \left\lceil\log\epsilon_1/\log \omega_1 \right\rceil \ \overset{\eqref{omega-tolerance}}{=} \ \left\lceil\log{2}/\log{r}\right\rceil  \
\le \ \log({\rho}_{\epsilon_1}\rho_0^{-1})/\log{r}+1.
\end{equation}
Notice that $\{\rho_k\}$ is either unchanged or increased by a ratio $r$ as $k$ increases.
By this fact and \eqref{T-epsilong}, we see that
\begin{equation}\label{rho:upper-bound-Tepsilong}
\max_{0 \le k \le K_{\epsilon_1}} \rho_k \le{r}^{K_{\epsilon_1}}\rho_0\overset{\eqref{T-epsilong}}{\le}{r}^{\frac{\log({\rho}_{\epsilon_1}\rho_0^{-1})}{\log{r}}+1}\rho_0={r}{\rho}_{\epsilon_1}.
\end{equation}
In addition, notice that $\rho_k>2\gamma$ and $\|\lambda^k\|\le \Lambda$. Using these, \eqref{hbd}, the first relation in \eqref{algstop:1st-order}, and Lemma \ref{tech-1}(ii) with $(x,\lambda,\rho)=(x^{k+1},\lambda^k,\rho_k)$,  we obtain that
\begin{equation}\label{bd-ck}\textstyle
\|\tilde{c}(x^{k+1})\| \le\sqrt{\frac{2(\fh-\fl+\gamma)}{\rho_k-2\gamma}+\frac{\|\lambda^k\|^2}{(\rho_k-2\gamma)^2}}+\frac{\|\lambda^k\|}{\rho_k-2\gamma}\le  \sqrt{\frac{2(\fh-\fl+\gamma)}{\rho_k-2\gamma}+\frac{\Lambda^2}{(\rho_k-2\gamma)^2}}+\frac{\Lambda}{\rho_k-2\gamma}.
\end{equation}
Also, we observe from $\|c(z_{\epsilon_1})\|\le\epsilon_1/2$ and the definition of $\tilde{c}$ in
\eqref{model:equa-cnstr-pert} that
\begin{equation}\label{bd-cxk}
\|c(x^{k+1})\|\le\|\tilde{c}(x^{k+1})\|+\|c(z_{\epsilon_1})\|\le \|\tilde{c}(x^{k+1})\|+\epsilon_1/2.
\end{equation}

We now prove that $\overline{K}_{\epsilon_1}$ is finite. Suppose for contradiction that $\overline{K}_{\epsilon_1}$ is infinite. It then follows from this and \eqref{number-outer-iteration} that $\|c(x^{k+1})\|>\epsilon_1$ for all $k\ge K_{\epsilon_1}$, which along with \eqref{bd-cxk} implies that $\|\tilde{c}(x^{k+1})\|>\epsilon_1/2$ for all $k\ge K_{\epsilon_1}$. It then follows that $\|\tilde{c}(x^{k+1})\|>\alpha\|\tilde{c}(x^k)\|$ must hold for infinitely many $k$'s. Using this and the update scheme on $\{\rho_k\}$, we deduce that $\rho_{k+1}={r}\rho_k$ holds for infinitely many $k$'s, which together with the monotonicity of $\{\rho_k\}$ implies that
$\rho_k\to\infty$ as $k\to\infty$. By this and \eqref{bd-ck}, one can see that  $\|\tilde{c}(x^{k+1})\|\to0$ as $k\to\infty$, which contradicts the fact that $\|\tilde{c}(x^{k+1})\|>\epsilon_1/2$ holds for all $k\ge K_{\epsilon_1}$. Hence, $\overline{K}_{\epsilon_1}$ is finite.
In addition, notice from \eqref{omega-tolerance}, \eqref{T-epsilon-g} and \eqref{epsw1-epsw2} that $(\tau_k^g,\tau_k^H)=(\epsilon_1,\epsilon_2)$ for all $k\ge K_{\epsilon_1}$. This along with the termination criterion of Algorithm \ref{alg:2nd-order-AL-nonconvex}  and the definition of $\overline{K}_{\epsilon_1}$ implies that Algorithm \ref{alg:2nd-order-AL-nonconvex} must terminate at iteration $\overline{K}_{\epsilon_1}$.

We next show that \eqref{outer-iteration-cmplxty} and $\rho_k\le{r}{\rho}_{\epsilon_1}$ hold for $0 \le k \le \overline{K}_{\epsilon_1}$ by considering two separate cases below.

Case 1) $\|c(x^{K_{\epsilon_1}+1})\|\le\epsilon_1$.  By this and \eqref{number-outer-iteration}, one can see that  $\overline{K}_{\epsilon_1}=K_{\epsilon_1}$, which together with \eqref{T-epsilong} and \eqref{rho:upper-bound-Tepsilong} implies that \eqref{outer-iteration-cmplxty} and $\rho_k\le{r}{\rho}_{\epsilon_1}$ hold for $0 \le k \le \overline{K}_{\epsilon_1}$.

Case 2) $\|c(x^{K_{\epsilon_1}+1})\|>\epsilon_1$. By this and \eqref{number-outer-iteration}, one can observe that $\overline{K}_{\epsilon_1}>K_{\epsilon_1}$  and also $\|c(x^{k+1})\|>\epsilon_1$ for all $K_{\epsilon_1} \le k \le \overline{K}_{\epsilon_1}-1$, which together with \eqref{bd-cxk} implies
\begin{equation}\label{lbd-tc}
\|\tilde{c}(x^{k+1})\|>\epsilon_1/2,\quad \forall K_{\epsilon_1} \le k \le \overline{K}_{\epsilon_1}-1.
\end{equation}
It then follows from $\|\lambda^k\|\le\Lambda$, \eqref{hbd}, the first relation in \eqref{algstop:1st-order}, and Lemma \ref{tech-1}(iv) with $(x,\lambda,\rho,\tdc)=(x^{k+1},\lambda^k,\rho_k,\epsilon_1/2)$ that
\begin{equation}\label{bound-rhok}
\begin{aligned}
\rho_k &< 8(\fh-\fl+\gamma)\epsilon_1^{-2}+4\|\lambda^k\|\epsilon_1^{-1}+2\gamma\\
&\le 8(\fh-\fl+\gamma)\epsilon_1^{-2}+4\Lambda\epsilon_1^{-1}+2\gamma\overset{\eqref{def:delta0c-rhobar1}}{\le}{\rho}_{\epsilon_1},\quad
\forall K_{\epsilon_1} \le k \le \overline{K}_{\epsilon_1}-1.
\end{aligned}
\end{equation}
Combining this relation, \eqref{rho:upper-bound-Tepsilong}, and the fact $\rho_{\overline{K}_{\epsilon_1}}\le {r}\rho_{\overline{K}_{\epsilon_1}-1}$, we conclude that  $\rho_k\le{r}{\rho}_{\epsilon_1}$ holds for $0 \le k\le \overline{K}_{\epsilon_1}$. It remains to
show that \eqref{outer-iteration-cmplxty} holds.  To this end, let 
\[
\bK =\{k:\rho_{k+1}={r}\rho_{k}, K_{\epsilon_1}\le k\le \overline{K}_{\epsilon_1}-2\}.
\]
It follows from \eqref{bound-rhok} and the update scheme of $\rho_k$ that 
\[
{r}^{|\bK|}\rho_{K_{\epsilon_1}}=\max_{K_{\epsilon_1}\le k \le \overline{K}_{\epsilon_1}-1}\{\rho_k\}\le {\rho}_{\epsilon_1},
\]
which together with $\rho_{K_{\epsilon_1}}\ge\rho_0$ implies that
\begin{equation}\label{bound-cU}
|\bK|\le \log({\rho}_{\epsilon_1}\rho_{K_{\epsilon_1}}^{-1})/ \log{r} \le \log({\rho}_{\epsilon_1}\rho_0^{-1})/ \log{r}.
\end{equation}
Let $\{k_1,k_2,\ldots,k_{|\bK|}\}$ denote all the elements of $\mathcal{\bK}$ arranged in ascending order, and let $k_0=K_{\epsilon_1}$ and $k_{|\bK|+1}=\overline{K}_{\epsilon_1}-1$. We next derive an upper bound for $k_{j+1}-k_{j}$ for $j=0,1,\ldots,|\bK|$. By the definition of $\bK$, one can observe that $\rho_{k}=\rho_{k'}$ for $k_j< k,k'\le k_{j+1}$. Using this and the update scheme of $\rho_k$, we deduce that
\begin{equation}\label{ineq:sequence-cxk}
\|\tilde{c}(x^{k+1})\|\le\alpha\|\tilde{c}(x^{k})\|,\quad \forall k_j<k< k_{j+1}.
\end{equation}
On the other hand, by \eqref{def:delta0c-rhobar1xxx}, \eqref{bd-ck} and $\rho_k\ge\rho_0$, one has $\|\tilde{c}(x^{k+1})\|\le \delta_{c,1}$ for $0 \le k \le \overline{K}_{\epsilon_1}$. By this and \eqref{lbd-tc}, one can see that
\begin{equation}\label{ineq:sequence-cxk2222}
\epsilon_1/2<\|\tilde{c}(x^{k+1})\|\le\delta_{c,1},\quad \forall K_{\epsilon_1} \le k \le \overline{K}_{\epsilon_1}-1.
\end{equation}
Now, note that either $k_{j+1} - k_j = 1$ or $k_{j+1} - k_j > 1$. In the latter case, we can apply \eqref{ineq:sequence-cxk} with $k = k_{j+1}-1,\ldots,k_j+1$ together with \eqref{ineq:sequence-cxk2222} to deduce that
\[
\epsilon_1/2<\|\tilde{c}(x^{k_{j+1}})\|\le\alpha \|\tilde{c}(x^{k_{j+1}-1})\|\le\cdots\le \alpha^{k_{j+1}-k_j-1}\|\tilde{c}(x^{k_{j}+1})\|\le \alpha^{k_{j+1}-k_j-1}\delta_{c,1},\quad \forall j=0,1,\ldots,|\bK|.
\]
Combining these two cases, we have 
\begin{equation}\label{ineq:subsequence-rho-same}
k_{j+1}-k_{j}\le |\log(\epsilon_1(2\delta_{c,1})^{-1}))/\log \alpha|+1,\quad \forall j=0,1,\ldots,|\bK|.
\end{equation}
