\begin{theorem}[{\bf iteration complexity of Algorithm \ref{alg:capped-CG}}]\label{lem:capped-CG}
Consider applying Algorithm~\ref{alg:capped-CG} with input $U = 0$ to the linear system~\eqref{indef-sys} with $g\neq 0$, $\varepsilon>0$, and $H$ being an $n\times n$ symmetric matrix. Then the number of iterations of Algorithm~\ref{alg:capped-CG} is $\widetilde{\cO}(\min\{n,\sqrt{\|H\|/\varepsilon}\})$.
\end{theorem}

\begin{proof}
From \cite[Lemma~1]{RNW18}, we know that the number of iterations of Algorithm \ref{alg:capped-CG} is bounded by $\min\{n,J(U,\varepsilon,\zeta)\}$, where $J(U,\varepsilon,\zeta)$ is the smallest integer $J$ such that $\sqrt{T}\tau^{J/2}\le\widehat{\zeta}$, with $U,\widehat{\zeta},T$ and $\tau$ being the values returned by Algorithm \ref{alg:capped-CG}. In addition, it was shown in \cite[Section 3.1]{RNW18} that
$J(U,\varepsilon,\zeta)\le\left\lceil \left(\sqrt{\kappa}+\frac{1}{2}\right)\ln\left(\frac{144(\sqrt{\kappa}+1)^2\kappa^6}{\zeta^2}\right)\right\rceil$,
where $\kappa={\cO}(U/\varepsilon)$ is an output by Algorithm \ref{alg:capped-CG}. Then one can see that $J(U,\varepsilon,\zeta)=\widetilde{\cO}(\sqrt{U/\varepsilon})$. Notice from
Algorithm~\ref{alg:capped-CG} that the output $U\le\|H\|$. Combining these, we obtain the conclusion as desired.
\end{proof}

\begin{theorem}[{\bf iteration complexity of Algorithm~\ref{pro:meo}}]\label{rand-Lanczos}
Consider Algorithm~\ref{pro:meo} with tolerance $\varepsilon>0$, probability parameter $\delta\in(0,1)$, and symmetric matrix $H\in\bR^{n\times n}$ as its input. Then it either finds a sufficiently negative curvature direction $v$ satisfying $v^THv\le-\varepsilon/2$ and $\|v\|=1$ or certifies that $\lambda_{\min}(H)\ge-\varepsilon$ holds with probability at least  $1-\delta$  in at most $N(\varepsilon,\delta)$ iterations, where $N(\varepsilon,\delta)$ is defined in \eqref{N-iter}.
\end{theorem}

