\begin{lemma}%[{{\bf level- and lower-boundedness of $\widetilde{\cL}(\cdot,\lambda^k;\rho_k)$}}]
\label{lem:level-set-augmented-lagrangian-func}
Suppose that Assumption~\ref{asp:lowbd-knownfeas} holds. Let $(\lambda^k, \rho_k)$ be generated at the $k$th iteration of Algorithm~\ref{alg:2nd-order-AL-nonconvex} for some $k \ge 0$, and $\cS(\bdelta_f,\bdelta_c)$ and $x_{\init}^k$ be defined in \eqref{nearly-feas-level-set} and \eqref{def:initial-iterate-subprob}, respectively, and let $\fh$, $\fl$, $\bdelta_f$ and $\bdelta_c$ be given in Assumption~\ref{asp:lowbd-knownfeas}. Suppose that $\rho_0$ is sufficiently large such that $\delta_{f,1} \le \bdelta_f$ and  $\delta_{c,1} \le \bdelta_c$, where 
\begin{equation} 
\delta_{f,1}:=\Lambda^2/(2\rho_0)\quad and\quad \delta_{c,1}:=\sqrt{\frac{2(\fh-\fl+\gamma)}{\rho_0-2\gamma}+\frac{\Lambda^2}{(\rho_0-2\gamma)^2}}+\frac{\Lambda}{\rho_0-2\gamma}\label{def:delta0c-rhobar1xxx}.
\end{equation}
Then the following statements hold.
\begin{enumerate}[{\rm (i)}]
\item $\{x:\widetilde{\cL}(x,\lambda^k;\rho_k)\le \widetilde{\cL}(x^{k}_{\init},\lambda^k;\rho_k)\}\subseteq \cS(\bdelta_f,\bdelta_c)$.
\item $\inf_{x\in\bR^n} \widetilde{\cL}(x,\lambda^k;\rho_k) \ge\fl - \gamma-\Lambda\bdelta_c$.
