\begin{equation}\label{def:critical-cone} 
\cC(x):=\{d\in\bR^n:\nabla c(x)^T d=0\}.
\end{equation}

\begin{definition}[{{\bf $\epsilon_1$-first-order stationary point}}]\label{def:FOSP}
Let $\epsilon_1>0$. We say that $x\in\bR^n$ is an $\epsilon_1$-first-order stationary point {\rm ($\epsilon_1$-FOSP)} of problem \eqref{model:equa-cnstr} if it, together with some $\lambda\in\bR^m$, satisfies 
\begin{equation}\label{optcond:1st-equa-cnstr} 
\|\nabla f(x)+\nabla c(x)\lambda\|\le \epsilon_1,\quad \|c(x)\|\le \epsilon_1.
\end{equation}
\end{definition}

\begin{definition}[{{\bf $(\epsilon_1,\epsilon_2)$-second-order stationary point}}]\label{def:SOSP}
Let $\epsilon_1,\epsilon_2>0$. We say that $x\in\bR^n$ is an $(\epsilon_1,
\epsilon_2)$-second-order stationary point {\rm (($\epsilon_1,
\epsilon_2$)-SOSP)} of problem \eqref{model:equa-cnstr} if it, together with some $\lambda\in\bR^m$, satisfies \eqref{optcond:1st-equa-cnstr} and additionally 
\begin{equation}\label{optcond:2nd-equa-cnstr} 
d^T\left(\nabla^2 f(x)+\sum_{i=1}^m\lambda_i\nabla^2 c_i(x)\right)d\ge-\epsilon_2\|d\|^2,\quad \forall d\in\cC(x),
\end{equation}
where $\cC(\cdot)$ is defined as in \eqref{def:critical-cone}.
\end{definition}

\begin{equation}\label{unconstrained-prob} 
\min_{x\in\bR^n}\ F(x),
\end{equation}

\begin{assumption}\label{asp:NCG-cmplxity}
\begin{enumerate}[{\rm (a)}]
\item The level set $\scL_F(u^0):=\{x: F(x)\le F(u^0)\}$ is compact for some $u^0\in \bR^n$.%, where $z^0\in\bR^n$ is the initial iterate of the Newton-CG method in \cite{RNW18}.
\item The function $F$ is twice Lipschitz continuously differentiable in
%{\color{black}some} convex open neighborhood $\Omega$ of $\{x|\  F(x)\le F(u^0)\}$,
%the convex hull of $\Omega$, denoted by $\conv(\Omega)$,
a convex open neighborhood, denoted by $\Omega$, of $\scL_F(u^0)$,
that is, there exists $L_{H}^F>0$ such that
\begin{equation}\label{F-Hess-Lip}
\|\nabla^2 F(x)-\nabla^2 F(y)\|\le L_{H}^F\|x-y\|,\quad \forall x,y\in \Omega.
\end{equation}
\end{enumerate}
\end{assumption}

By Assumption \ref{asp:NCG-cmplxity}, there exist $\Fl\in \bR$, $U_g^F>0$ and $U_H^F>0$ such that
\begin{equation}\label{lwbd-Hgupbd}
F(x)\ge \Fl,\quad \|\nabla F(x)\|\le U_g^F,\quad \|\nabla^2 F(x)\|\le U_H^F, \quad \forall x\in\scL_F(u^0).
\end{equation}

The first main component of the Newton-CG method in \cite{RNW18} is a {\it capped CG method} \cite[Algorithm~1]{RNW18}, which is a modified CG method, for solving a possibly indefinite linear system 
\begin{equation}\label{indef-sys} 
(H+2\varepsilon I)d=-g,
\end{equation}

\begin{algorithm}[h]
\caption{A Newton-CG method for problem \eqref{unconstrained-prob}}
\label{alg:NCG}
{\footnotesize
\begin{algorithmic}
\State \noindent\textit{Input}: Tolerances $\epsilon_g,\epsilon_H\in(0,1)$, backtracking ratio $\theta\in(0,1)$, starting point $u^0$, CG-accuracy parameter $\zeta\in(0,1)$, line-search parameter $\eta\in(0,1)$, probability parameter $\delta\in(0,1)$.\\
Set $x^0=u^0$;
\For{$t=0,1,2,\ldots$}
\If{$\|\nabla F(x^t)\|>\epsilon_g$}
\State Call Algorithm~\ref{alg:capped-CG} with $H=\nabla^2 F(x^t)$, $\varepsilon=\epsilon_H$, $g=\nabla F(x^t)$, accuracy parameter $\zeta$, and $U=0$ to obtain outputs $d$,
\State d$\_$type;
\If{d$\_$type=NC}
%\State
\begin{equation}\label{dk-nc}
d^t\leftarrow -\sgn(d^T\nabla F(x^t))\frac{|d^T\nabla^2 F(x^t) d|}{\|d\|^3}d;
\end{equation}
\Else\ \{d$\_$type=SOL\}
%\State
\begin{equation}\label{dk-sol}
d^t\leftarrow d;
\end{equation}
\EndIf
\State Go to {\bf Line Search};
\Else
\State Call Algorithm~\ref{pro:meo} with $H=\nabla^2 F(x^t)$, $\varepsilon=\epsilon_H$, and probability parameter $\delta$;
\If{Algorithm~\ref{pro:meo} certifies that $\lambda_{\min}(\nabla^2 F(x^t))\ge-\epsilon_H$}
\State Output $x^t$ and terminate;
\Else\ \{Sufficiently negative curvature direction $v$ returned by Algorithm~\ref{pro:meo}\}
\State Set d$\_$type=NC and
\begin{equation}\label{dk-2nd-nc}
d^t\leftarrow -\sgn(v^T\nabla F(x^t))|v^T\nabla^2F(x^t)v|v;
\end{equation}
\State Go to {\bf Line Search};
\EndIf
\EndIf
\State{\bf Line Search:}
\If{d$\_$type=SOL}
\State Find $\alpha_t=\theta^{j_t}$, where $j_t$ is the smallest nonnegative integer $j$ such that
\begin{equation}\label{ls-sol}
F(x^t+\theta^jd^t)<F(x^t)-\eta\epsilon_H\theta^{2j}\|d^t\|^2;
\end{equation}
\Else\ \{d$\_$type=NC\}
\State Find $\alpha_t=\theta^{j_t}$, where $j_t$ is the smallest nonnegative integer $j$ such that
\begin{equation}\label{ls-nc}
F(x^t+\theta^jd^t)<F(x^t)-\eta\theta^{2j}\|d^t\|^3/2;
\end{equation}
\EndIf
\State $x^{t+1}=x^t+\alpha_td^t$;
\EndFor
\end{algorithmic}
}
\end{algorithm}

\begin{assumption}\label{asp:lowbd-knownfeas}		
\begin{enumerate}[{\rm (a)}]
\item An $\epsilon_1/2$-approximately feasible point $z_{\epsilon_1}$ of problem~\eqref{model:equa-cnstr}, namely satisfying $\|c(z_{\epsilon_1})\|\le\epsilon_1/2$, is known.	
\item There exist constants $\fh$, $\fl$ and $\gamma>0$, independent of $\epsilon_1$ and $\epsilon_2$,  such that
\begin{eqnarray}
&& f(z_{\epsilon_1})\le\fh, \label{hbd}\\
&& f(x)+\gamma\|c(x)\|^2/2\ge \fl,\quad \forall x\in\bR^n, \label{lbd}
\end{eqnarray}
 where $z_{\epsilon_1}$ is given in (a).
\item %{  For any $\epsilon \in (0,1)$ and the corresponding $z^0$ from (b),}
There exist some $\bdelta_f,\bdelta_c>0$ such that the set
\begin{equation}\label{nearly-feas-level-set}
\cS(\bdelta_f,\bdelta_c):=\{x:f(x)\le \fh+\bdelta_f,\ \|c(x)\|\le1+\bdelta_c\}
\end{equation}
%is compact, { with $\fh$ as in \eqref{hbd}}. 
is compact with $\fh$ given above. Also, $\nabla^2 f$ and $\nabla^2 c_i,\ i=1,2,\ldots,m$, are Lipschitz continuous in a convex open neighborhood, denoted by $\Omega(\bdelta_f,\bdelta_c)$, of $\cS(\bdelta_f,\bdelta_c)$.
